import{_ as p,C as l,o as r,c as m,a9 as a,b as n,w as t,a as i,E as o,a8 as d}from"./chunks/framework.BOiBTRPC.js";const T=JSON.parse(`{"title":"Flink & Beam","description":"Flink's checkpointed runtime for stateful streaming, Beam's portable programming model — and where each fits against Kafka Streams and Spark.","frontmatter":{"title":"Flink & Beam","description":"Flink's checkpointed runtime for stateful streaming, Beam's portable programming model — and where each fits against Kafka Streams and Spark."},"headers":[],"relativePath":"streaming/flink-beam.md","filePath":"streaming/flink-beam.md"}`),u={name:"streaming/flink-beam.md"};function g(k,e,b,f,y,w){const s=l("Mermaid"),h=l("BackpressureViz"),c=l("QuizCard");return r(),m("div",null,[e[5]||(e[5]=a('<h1 id="flink-beam" tabindex="-1">Flink &amp; Beam <a class="header-anchor" href="#flink-beam" aria-label="Permalink to &quot;Flink &amp; Beam&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — When the job is &quot;aggregate a Kafka topic per user per minute, tolerate failures, replay cleanly,&quot; the engine choice decides whether recovery takes seconds or a night of deduplication. Flink is the default stateful-streaming engine today; Beam is the model you write when portability (Dataflow, Flink, Spark) is a requirement, not a preference.</p></blockquote><h2 id="flink-runtime" tabindex="-1">Flink runtime <a class="header-anchor" href="#flink-runtime" aria-label="Permalink to &quot;Flink runtime&quot;">​</a></h2><p>A Flink cluster is a <strong>JobManager</strong> (coordinator: scheduling, checkpoint triggering, failure recovery) plus <strong>TaskManagers</strong> (workers running parallel operator subtasks in <strong>slots</strong>). The job graph — sources, keyed operators, sinks — is chopped into tasks that hold local <strong>state</strong>.</p>',4)),(r(),n(d,null,{default:t(()=>[o(s,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20JM%5B%22JobManager%3Cbr%2F%3Escheduling%20%C2%B7%20checkpoint%20coordinator%20%C2%B7%20failover%22%5D%0A%20%20%20%20subgraph%20TM1%5B%22TaskManager%201%22%5D%0A%20%20%20%20%20%20%20%20S1%5B%22Slot%3A%20Source%20%E2%86%92%20Map%22%5D%0A%20%20%20%20%20%20%20%20S2%5B%22Slot%3A%20Keyed%20Window%3Cbr%2F%3E(state%3A%20RocksDB)%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20TM2%5B%22TaskManager%202%22%5D%0A%20%20%20%20%20%20%20%20S3%5B%22Slot%3A%20Source%20%E2%86%92%20Map%22%5D%0A%20%20%20%20%20%20%20%20S4%5B%22Slot%3A%20Sink%3Cbr%2F%3E(2PC%20committer)%22%5D%0A%20%20%20%20end%0A%20%20%20%20K%5B%22Kafka%20source%22%5D%20--%3E%20S1%20%26%20S3%0A%20%20%20%20S1%20--%3E%20S2%0A%20%20%20%20S3%20--%3E%20S2%0A%20%20%20%20S2%20--%3E%20S4%0A%20%20%20%20S4%20--%3E%20OUT%5B%22Sink%3A%20Kafka%20%2F%20JDBC%20%2F%20files%22%5D%0A%20%20%20%20JM%20-.-%3E%7C%22triggers%20checkpoints%22%7C%20TM1%0A%20%20%20%20JM%20-.-%3E%7C%22triggers%20checkpoints%22%7C%20TM2%0A%20%20%20%20S2%20-.-%3E%7C%22snapshot%20state%22%7C%20FS%5B%22Durable%20storage%3Cbr%2F%3E(S3%20%2F%20HDFS)%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=a('<p>Key vocabulary for interviews:</p><ul><li><strong>Operator state vs keyed state</strong> — operator state is per-subtask (a Kafka source&#39;s partition offsets); keyed state is per-key (<code>ValueState</code>, <code>MapState</code>, <code>ListState</code>) and redistributed on rescaling via key groups.</li><li><strong>Parallelism</strong> — each operator&#39;s subtask count; keyed state can only rescale within <code>maxParallelism</code> key groups.</li><li><strong>Task chaining</strong> — adjacent operators fuse into one task, avoiding serialization and network hops.</li></ul><h3 id="keyed-state-primitives" tabindex="-1">Keyed state primitives <a class="header-anchor" href="#keyed-state-primitives" aria-label="Permalink to &quot;Keyed state primitives&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Primitive</th><th>Shape</th><th>Typical use</th></tr></thead><tbody><tr><td><code>ValueState&lt;T&gt;</code></td><td>one value per key</td><td>last-seen event, running count</td></tr><tr><td><code>ListState&lt;T&gt;</code></td><td>list per key</td><td>buffered records for a key</td></tr><tr><td><code>MapState&lt;K,V&gt;</code></td><td>map per key</td><td>per-key dictionaries, joins</td></tr><tr><td><code>ReducingState</code> / <code>AggregatingState</code></td><td>incremental combine</td><td>sums, merges — never materialize the list</td></tr><tr><td><code>MapState</code> + timers</td><td>event/proc-time timers per key</td><td>session gaps, timeouts, TTL-like logic</td></tr></tbody></table><p>Keyed state is sharded into <strong>key groups</strong> — the rescaling unit. <code>maxParallelism</code> fixes how many key groups exist at job start; you can only rescale to parallelism ≤ that number without a full state migration. Set it at first deploy, not after the state is real.</p><p>Rescaling never moves individual keys — it remaps <strong>whole key groups</strong> to subtasks, which is what makes scale-out/in cheap and deterministic. Each key hashes into exactly one of <code>maxParallelism</code> key groups; the number of key groups assigned per subtask just changes. The same repartitioning logic applies on <em>any</em> stateful-parallelism change, including savepoint restores at a different parallelism. The non-keyed operators scale differently: operator <strong>list state</strong> redistributes entries evenly, <strong>union list state</strong> broadcasts the full list to every new task (each keeps what it needs), and <strong>broadcast state</strong> is simply copied — downscaling just cancels surplus tasks.</p>',6)),(r(),n(d,null,{default:t(()=>[o(s,{id:"mermaid-116",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20kg%5B%22Keyed%20operator%20%E2%80%94%20before%22%5D%0A%20%20%20%20%20%20%20%20K1%5B%22Task%201%3Cbr%2F%3Ekey%20groups%200%2C1%22%5D%0A%20%20%20%20%20%20%20%20K2%5B%22Task%202%3Cbr%2F%3Ekey%20groups%202%2C3%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20kg2%5B%22After%20scale-out%20to%204%22%5D%0A%20%20%20%20%20%20%20%20T1%5B%22Task%201%3Cbr%2F%3Ekg%200%22%5D%0A%20%20%20%20%20%20%20%20T2%5B%22Task%202%3Cbr%2F%3Ekg%201%22%5D%0A%20%20%20%20%20%20%20%20T3%5B%22Task%203%3Cbr%2F%3Ekg%202%22%5D%0A%20%20%20%20%20%20%20%20T4%5B%22Task%204%3Cbr%2F%3Ekg%203%22%5D%0A%20%20%20%20end%0A%20%20%20%20K1%20--%3E%7C%22kg%201%20migrates%22%7C%20T2%0A%20%20%20%20K1%20--%3E%20T1%0A%20%20%20%20K2%20--%3E%20T3%0A%20%20%20%20K2%20--%3E%7C%22kg%203%20migrates%22%7C%20T4%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=a('<h3 id="sizing-slots-vs-taskmanagers" tabindex="-1">Sizing slots vs TaskManagers <a class="header-anchor" href="#sizing-slots-vs-taskmanagers" aria-label="Permalink to &quot;Sizing slots vs TaskManagers&quot;">​</a></h3><p>A <strong>TaskManager is a JVM process</strong>; a <strong>slot is a slice of that process</strong> that runs one parallel slice of the whole job — one subtask of <em>each</em> operator — as a thread. All tasks in a TM share its heap, network stack, and fate: one misbehaving task can kill the process and every task on it.</p><table tabindex="0"><thead><tr><th>Decision</th><th>Consequence</th><th>Rule of thumb</th></tr></thead><tbody><tr><td>Many slots per TM</td><td>Cheap colocation — chained/local tasks exchange data in-process, no network</td><td>Default for throughput; watch for one bad task taking siblings down</td></tr><tr><td>One slot per TM</td><td>Hard isolation per job slice; failure blast radius = one task</td><td>Unstable UDFs, mixed-tenant clusters</td></tr><tr><td>Several TMs per host</td><td>Threads for parallelism + processes for isolation</td><td>The standard production topology</td></tr><tr><td>Slots vs cores</td><td><code>slots ≈ CPU cores</code> per TM is the classic starting point; I/O-heavy jobs can oversubscribe</td><td>Measure CPU vs state-access wait before adding slots</td></tr></tbody></table><p>Two constraints the model implies: the job needs <strong>as many slots as its maximum operator parallelism</strong> (a pipeline with a <code>parallelism=4</code> operator needs ≥4 free slots, period), and network buffer demand grows <strong>quadratically</strong> with task count on shuffle/broadcast connections — each sending task needs a dedicated buffer per receiving task. A job that ran fine small can wedge at scale on buffer starvation, not CPU.</p><h2 id="deployment-session-application-kubernetes" tabindex="-1">Deployment: session, application, Kubernetes <a class="header-anchor" href="#deployment-session-application-kubernetes" aria-label="Permalink to &quot;Deployment: session, application, Kubernetes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Cluster lifecycle</th><th>Where it fits</th></tr></thead><tbody><tr><td><strong>Session</strong></td><td>Long-lived cluster; many jobs submit to it</td><td>Shared dev clusters, mixed workloads — resource contention is your problem</td></tr><tr><td><strong>Application (K8s)</strong></td><td>Cluster per job/app; JM+TMs are pods, autoscaled</td><td>Production default — isolation, savepointed upgrades, native HA</td></tr><tr><td><strong>YARN</strong></td><td>Legacy Hadoop-era resource manager</td><td>Older on-prem estates; largely replaced by K8s operator</td></tr></tbody></table><p>The <strong>Flink Kubernetes Operator</strong> is the production standard now: declare a <code>FlinkDeployment</code> and it handles JobManager HA via K8s leader election, savepoint-on-upgrade, and autoscaler integration.</p><h2 id="checkpoints-barrier-alignment" tabindex="-1">Checkpoints: barrier alignment <a class="header-anchor" href="#checkpoints-barrier-alignment" aria-label="Permalink to &quot;Checkpoints: barrier alignment&quot;">​</a></h2><p>Flink&#39;s fault tolerance is a <strong>distributed snapshot</strong> of all operator state, triggered by the JobManager inserting <strong>checkpoint barriers</strong> into the data stream. When a barrier reaches an operator, the operator snapshots its state; barriers flow with the stream, so a snapshot is a consistent cut — &quot;every record before barrier <em>n</em> has been applied.&quot;</p>',9)),(r(),n(d,null,{default:t(()=>[o(s,{id:"mermaid-249",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20JM%20as%20JobManager%0A%20%20%20%20participant%20Src%20as%20Source%0A%20%20%20%20participant%20Op%20as%20Window%20Operator%0A%20%20%20%20participant%20Sink%20as%20Sink%0A%0A%20%20%20%20JM-%3E%3ESrc%3A%20inject%20barrier%20%2342%0A%20%20%20%20Src-%3E%3ESrc%3A%20snapshot%20offsets%20%E2%86%92%20storage%0A%20%20%20%20Src-%3E%3EOp%3A%20barrier%20flows%20downstream%0A%20%20%20%20Note%20over%20Op%3A%20multi-input%20op%3A%3Cbr%2F%3Ealign%20%E2%80%94%20buffer%20faster%3Cbr%2F%3Einput%20until%20barrier%3Cbr%2F%3Earrives%20on%20all%20inputs%0A%20%20%20%20Op-%3E%3EOp%3A%20snapshot%20keyed%20state%20(async)%0A%20%20%20%20Op-%3E%3ESink%3A%20barrier%20flows%20downstream%0A%20%20%20%20Sink-%3E%3ESink%3A%20snapshot%20%2B%20pre-commit%20(2PC)%0A%20%20%20%20Sink-%3E%3EJM%3A%20ack%20%E2%80%94%20checkpoint%2042%20complete%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[i(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=a('<p>With <strong>multiple inputs</strong>, an operator must <em>align</em>: it stops processing the input where the barrier already arrived until the barrier arrives on all inputs. Under backpressure, alignment stalls — which is why <strong>unaligned checkpoints</strong> exist: the barrier overtakes buffered records and the in-flight data is snapshotted too, so checkpointing keeps working when the pipeline is lagging. On Flink 1.x they are opt-in via <code>execution.checkpointing.unaligned.enabled</code>; from Flink 2.0 (FLIP-413) they are the default.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Long checkpoints are a symptom</p><p>Checkpoint duration growing toward the interval means state is too big, RocksDB is I/O-bound, or backpressure is blocking barrier flow. <code>checkpointingMode: UNALIGNED</code> and incremental RocksDB snapshots are the first levers — not a longer interval, which just delays the crash.</p></div><h3 id="backpressure-propagation" tabindex="-1">Backpressure propagation <a class="header-anchor" href="#backpressure-propagation" aria-label="Permalink to &quot;Backpressure propagation&quot;">​</a></h3><p>Flink&#39;s flow control is <strong>credit-based</strong>: each downstream input channel announces buffer credits upstream; a task whose output buffers are all occupied stops emitting, and that blockage propagates back to the source, which simply stops polling Kafka. There is no &quot;slow consumer signal&quot; — backpressure <em>is</em> the signal, and it shows up as checkpoint alignment stalls and <code>outPoolUsage</code>/<code>inPoolUsage</code> saturation before anything errors.</p>',4)),o(h),e[9]||(e[9]=a('<p>Run the producer faster than the consumer. With backpressure <strong>ON</strong>, the receiver only grants as many buffer credits as it can drain, so the sender&#39;s effective rate collapses to the consumer&#39;s — the backlog notification even lets the receiver prioritize which senders get the next credits. With it <strong>OFF</strong>, the bounded buffer fills and events drop. That is the whole mechanism: Flink never tells upstream to slow down; it simply stops handing out credits, and the stall propagates hop by hop until the source stops polling Kafka.</p><h3 id="async-i-o-and-async-state-api" tabindex="-1">Async I/O and Async State API <a class="header-anchor" href="#async-i-o-and-async-state-api" aria-label="Permalink to &quot;Async I/O and Async State API&quot;">​</a></h3><p>Two workhorses worth naming: <strong>Async I/O</strong> (<code>AsyncDataStream</code>) for enrichment calls to external services — unordered or ordered waits without blocking the operator thread — and <strong>Async State Access</strong> (State V2, Flink 2.x), which removes RocksDB&#39;s synchronous get/put latency from the processing path for state-heavy jobs.</p><h2 id="exactly-once-end-to-end-the-two-phase-commit-sink" tabindex="-1">Exactly-once end-to-end: the two-phase-commit sink <a class="header-anchor" href="#exactly-once-end-to-end-the-two-phase-commit-sink" aria-label="Permalink to &quot;Exactly-once end-to-end: the two-phase-commit sink&quot;">​</a></h2><p>Checkpoints make <em>internal</em> state exactly-once. To extend that to the sink, Flink&#39;s <code>TwoPhaseCommitSinkFunction</code> ties external writes to the checkpoint cycle — the protocol maps cleanly onto it:</p><ol><li><strong><code>beginTransaction</code></strong> — before the first record (and after every barrier), the sink opens a transaction on the external system: a Kafka transaction, a temp file, an uncommitted DB transaction.</li><li><strong><code>invoke</code></strong> — every record between barriers is written <em>inside</em> the open transaction — visible to the sink system but not committed.</li><li><strong><code>preCommit</code></strong> — on barrier arrival, the sink flushes/stages the transaction, snapshots the transaction handle as state, and acks the checkpoint. This ack is the 2PC &quot;commit vote.&quot;</li><li><strong><code>commit</code></strong> — when the JobManager broadcasts checkpoint-complete (every task acked), all parallel sink instances commit together. This notification is the 2PC &quot;commit command.&quot;</li><li><strong><code>abort</code></strong> — on failure before completion, the pending transaction is rolled back; recovery resumes from the last completed checkpoint.</li></ol><p>Because voting piggybacks on the regular checkpoint, 2PC costs almost nothing per record — it runs once per checkpoint interval, not per message. The hard part is the <em>contract the sink system must honor</em>:</p><ul><li><strong>Transactional writes</strong> — data written must not be visible before commit (or transactions must be emulated, e.g. temp-file → atomic rename).</li><li><strong>Transaction survives a checkpoint interval</strong> — and longer during recovery; a sink-side timeout that closes the transaction loses data.</li><li><strong>Recoverable transaction handle</strong> — a transaction ID the sink can commit or abort after a process crash.</li><li><strong>Idempotent commit</strong> — a repeated commit after recovery must be a no-op.</li></ul><p>Once a sink task has <em>acked</em> a checkpoint, it <strong>must</strong> be able to commit that transaction even across a crash — that invariant is the whole exactly-once guarantee.</p><h3 id="the-end-to-end-exactly-once-checklist" tabindex="-1">The end-to-end exactly-once checklist <a class="header-anchor" href="#the-end-to-end-exactly-once-checklist" aria-label="Permalink to &quot;The end-to-end exactly-once checklist&quot;">​</a></h3><p>Checkpoints only make <em>internal</em> state consistent. End-to-end exactly-once is a property of the whole chain — the book&#39;s consistency matrix:</p><table tabindex="0"><thead><tr><th></th><th>Non-resettable source</th><th>Resettable source</th></tr></thead><tbody><tr><td>Any (plain) sink</td><td>At-most-once</td><td>At-least-once</td></tr><tr><td>Idempotent sink</td><td>At-most-once</td><td>Exactly-once* — transient inconsistencies while replaying</td></tr><tr><td>WAL sink</td><td>At-most-once</td><td>At-least-once</td></tr><tr><td>2PC sink</td><td>At-most-once</td><td><strong>Exactly-once</strong></td></tr></tbody></table><p>The requirements, in order:</p><ol><li><strong>Source must be resettable</strong> — it must persist its read position in checkpointed state and be able to rewind: Kafka partition offsets, file byte offsets. A socket source discards data once consumed — no reset, no better than at-most-once, full stop.</li><li><strong>All state checkpointed</strong> — every operator&#39;s state lands in the snapshot.</li><li><strong>Sink must be transactional or idempotent</strong> — 2PC (writes only materialize on checkpoint completion) or deterministic upserts (idempotent writes can momentarily show rolled-back results during replay — &quot;jump back in time&quot; — before converging).</li></ol><p>The WAL-sink alternative — buffer all output in state, flush on checkpoint-complete — works with <em>any</em> sink system but bloats state, emits in spikes, and only reaches at-least-once in edge cases. Prefer 2PC when the sink supports transactions. Kafka sinks get this free (<code>delivery.guarantee=EXACTLY_ONCE</code> wraps Kafka transactions); JDBC sinks achieve it via XA or upsert-and-dedup. The checkpoint completes only when every participant acks — one consistent epoch across state, offsets, and side effects.</p><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Exactly-once is a <em>pipeline property</em>, not a connector feature. The chain is: idempotent/transactional source replay → consistent state snapshot → atomic sink commit. Any non-transactional leg (an HTTP API call, a fire-and-forget side output) silently drops you to at-least-once — plan for it explicitly.</p></div><h2 id="state-backends" tabindex="-1">State backends <a class="header-anchor" href="#state-backends" aria-label="Permalink to &quot;State backends&quot;">​</a></h2><p>Where keyed/operator state physically lives:</p><table tabindex="0"><thead><tr><th></th><th><strong>HashMap / embedded heap</strong> (<code>HashMapStateBackend</code>)</th><th><strong>RocksDB</strong> (<code>EmbeddedRocksDBStateBackend</code>)</th></tr></thead><tbody><tr><td>State location</td><td>JVM heap + snapshots to storage</td><td>Local disk (embedded LSM) + incremental snapshots to storage</td></tr><tr><td>Max state size</td><td>Heap-bound — GBs risky, GC pressure</td><td>Practically unbounded — TBs common</td></tr><tr><td>Read/write latency</td><td>In-memory, fastest</td><td>Per-access disk/serialization cost (~10–50 µs)</td></tr><tr><td>Snapshots</td><td>Full — cost grows with state</td><td>Incremental — only changed SSTables upload</td></tr><tr><td>Recovery</td><td>Reload entire state from snapshot</td><td>Restore changed files only — faster catch-up</td></tr><tr><td>Use when</td><td>Small state, lowest latency</td><td>Any production job with GBs+ of state</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">ℹ️ The practical rule</p><p>Dev and small-state jobs: heap. Anything with keyed windows over real traffic or joins across days: RocksDB with incremental checkpoints and <code>state.ttl</code> set — otherwise state grows until the job falls over, and &quot;the job worked for three months&quot; is not a coincidence, it&#39;s a memory leak you called steady state.</p></div><h2 id="savepoints-vs-checkpoints" tabindex="-1">Savepoints vs checkpoints <a class="header-anchor" href="#savepoints-vs-checkpoints" aria-label="Permalink to &quot;Savepoints vs checkpoints&quot;">​</a></h2><p>Both are snapshots of the same mechanism; they differ in <em>who triggers them and why</em>.</p><table tabindex="0"><thead><tr><th></th><th>Checkpoint</th><th>Savepoint</th></tr></thead><tbody><tr><td>Trigger</td><td>Automatic, periodic</td><td>Manual (<code>flink savepoint &lt;job&gt;</code>) or CLI/API on deploy</td></tr><tr><td>Purpose</td><td>Failure recovery — restart in place</td><td>Planned ops: upgrades, rescaling, code changes, A/B rollouts</td></tr><tr><td>Retention</td><td>Rotated (keep-last-N), owned by the job</td><td>Retained until deleted, owned by the operator</td></tr><tr><td>Format stability</td><td>Internal — can change between versions</td><td>Stable/portable across versions by contract</td></tr></tbody></table><h3 id="savepoint-compatible-evolution-—-what-breaks-a-savepoint" tabindex="-1">Savepoint-compatible evolution — what breaks a savepoint <a class="header-anchor" href="#savepoint-compatible-evolution-—-what-breaks-a-savepoint" aria-label="Permalink to &quot;Savepoint-compatible evolution — what breaks a savepoint&quot;">​</a></h3><p>Savepoint state is indexed by <strong>operator <code>uid</code> + state name</strong>, not by task. A modified job can only adopt savepoint state where the new graph has a matching uid. Since default uids are generated from each operator&#39;s position in the graph, any structural edit silently re-ids everything downstream.</p><table tabindex="0"><thead><tr><th>Change</th><th>Savepoint survives?</th></tr></thead><tbody><tr><td>Change parallelism of any operator</td><td>✅ — state redistributes by key group</td></tr><tr><td>Swap function logic, same uid, same state schema</td><td>✅ — this is the point of savepoints</td></tr><tr><td>Add a new operator mid-graph</td><td>✅ with manual uids; ❌ with generated uids (downstream ids shift)</td></tr><tr><td>Remove an operator that held state</td><td>⚠️ — its savepointed state is orphaned/unrestorable</td></tr><tr><td>Change a state field&#39;s type or serializer</td><td>❌ — schema mismatch on restore</td></tr><tr><td>Rescale keyed state beyond <code>maxParallelism</code></td><td>❌ — key groups can&#39;t split further; requires state migration</td></tr><tr><td>Restore a job that never had <code>uid()</code>s set</td><td>❌ — ids don&#39;t line up; effectively starting fresh</td></tr></tbody></table><p>Rule: assign <code>uid()</code> to every operator <strong>before the first stateful deploy</strong> — retrofitting uids onto a running job means abandoning its current savepoints.</p><p>The standard deploy dance: <code>savepoint</code> → cancel job → redeploy new jar with <code>--fromSavepoint</code>. Skip it and you either lose state or recover from a checkpoint that may not match the new job graph.</p><h2 id="failure-modes-you-ll-actually-see" tabindex="-1">Failure modes you&#39;ll actually see <a class="header-anchor" href="#failure-modes-you-ll-actually-see" aria-label="Permalink to &quot;Failure modes you&#39;ll actually see&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Real cause</th><th>First lever</th></tr></thead><tbody><tr><td>Checkpoint timeout / slow alignment</td><td>Backpressure upstream of the barrier, or state too large</td><td>Unaligned checkpoints; incremental RocksDB; find the saturated task first</td></tr><tr><td>State grows forever</td><td>Missing <code>state.ttl</code>, or allowed lateness wider than needed</td><td>TTL matched to the window semantics — see <a href="/Data-Knowledge/streaming/windows-watermarks.html">Windows &amp; Watermarks</a></td></tr><tr><td>Recovery takes minutes</td><td>Full state restore from remote storage on every restart</td><td>Local recovery (task-local state), fewer restarts, smaller state</td></tr><tr><td>Job &quot;works&quot; until deploy</td><td>Graph changed between savepoint and new jar; operator <code>uid</code> drift</td><td>Always <code>uid()</code> every operator so savepoints map cleanly</td></tr><tr><td>Sinks emit duplicates after restart</td><td>Non-2PC sink replaying post-checkpoint records</td><td>Transactional/idempotent sink, or accept at-least-once and dedup downstream</td></tr><tr><td>Lag grows steadily</td><td>Parallelism can&#39;t keep up with input rate</td><td>More parallelism on the bottleneck operator, or fewer per-record costs (chaining, avoid serialization)</td></tr><tr><td>Job won&#39;t restart after a TM died</td><td>Remaining slots &lt; max operator parallelism — job needs slots ≥ widest operator, not average</td><td>More TMs/slots, or reduce parallelism; the JM waits rather than degrade</td></tr><tr><td>Throughput collapses at larger scale</td><td>Network buffers quadratic in task pairs on shuffle/broadcast connections</td><td>More TM network buffers; break chains so fewer channels multiplex</td></tr><tr><td>Checkpoints always running, processing starved</td><td>Checkpoint duration ≥ interval; only one in-flight by default</td><td><code>minPauseBetweenCheckpoints</code> to protect processing; <code>maxConcurrentCheckpoints</code> only when checkpoints are slow-but-cheap</td></tr><tr><td>Recovery replays minutes of duplicates</td><td>Long checkpoint interval + non-transactional sink</td><td>Shorter interval, or a 2PC/idempotent sink</td></tr><tr><td>One task&#39;s OOM kills half the job</td><td>Slots are threads in one JVM — no fault isolation inside a TM</td><td>Fewer slots per TM / more TMs per host for blast radius</td></tr><tr><td>Checkpoints slow with heavy timers</td><td>Heap-stored timers checkpoint synchronously under RocksDB incremental</td><td>RocksDB-managed timers; bound timer cardinality per key</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">ℹ️ uid() is the cheapest insurance</p><p>Every operator you don&#39;t name gets an auto-generated uid from its position in the job graph — which changes the moment you reorder code. Name operators once (<code>uid(&quot;window-agg&quot;)</code>) and every future savepoint survives refactors.</p></div><h3 id="event-time-timers-and-the-process-function-pattern" tabindex="-1">Event-time timers and the process-function pattern <a class="header-anchor" href="#event-time-timers-and-the-process-function-pattern" aria-label="Permalink to &quot;Event-time timers and the process-function pattern&quot;">​</a></h3><p><code>KeyedProcessFunction</code> is the escape hatch when windows can&#39;t express the logic. <code>processElement</code> sees each record plus a <code>Context</code> carrying the record&#39;s timestamp, key, and a <code>TimerService</code>; <code>onTimer</code> fires callbacks. Two timer domains: <code>registerProcessingTimeTimer</code> (wall clock of the machine) and <code>registerEventTimeTimer</code> (fires when the <strong>watermark</strong> reaches the timestamp — this is how you get &quot;no event for this key in 30 min of <em>event</em> time&quot;).</p>',33)),(r(),n(d,null,{default:t(()=>[o(s,{id:"mermaid-837",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20E%5B%22event%20per%20key%22%5D%20--%3E%20PE%5B%22processElement%3Cbr%2F%3Eupdate%20state%3Cbr%2F%3Eregister%20timer%22%5D%0A%20%20%20%20PE%20--%3E%20ST%5B%22keyed%20state%3Cbr%2F%3E(ValueState%20etc.)%22%5D%0A%20%20%20%20PE%20--%3E%20TS%5B%22TimerService%3Cbr%2F%3EregisterEventTimeTimer(t)%22%5D%0A%20%20%20%20TS%20--%3E%7Cwatermark%20%E2%89%A5%20t%7C%20OT%5B%22onTimer%3Cbr%2F%3Eread%20state%20%C2%B7%20emit%20%C2%B7%20clean%20up%22%5D%0A%20%20%20%20OT%20--%3E%20ST%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[i(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=a('<p>The pattern that makes it powerful: <strong>state + timer = arbitrary per-key logic</strong> — session reconstruction, &quot;emit if no second event within X,&quot; TTL-style expiry, custom windows — with <code>processElement</code> and <code>onTimer</code> synchronized so state access is single-threaded per key.</p><p>The mechanics worth memorizing:</p><ul><li><strong>One timer per key per timestamp</strong> — re-registering the same timestamp is a no-op; a key may hold many timers at different timestamps.</li><li><strong>Timers are checkpointed state</strong> — processing-time timers that expired during downtime fire immediately on resume (expect a burst); timers restored from savepoints behave the same.</li><li><strong>Past timestamps are not dropped</strong> — processing-time timers fire right away; event-time timers fire on the next watermark.</li><li><strong>Timers live on heap by default</strong> — a priority queue per key. With RocksDB incremental checkpoints, heap timers are checkpointed <em>synchronously</em>: millions of timers = slow checkpoints. Configure RocksDB-managed timers or keep timer counts bounded.</li><li><strong>Timers require a keyed stream</strong> — a constant <code>KeySelector</code> key works but collapses the operator to parallelism 1.</li></ul><h3 id="flink-sql-and-the-table-api" tabindex="-1">Flink SQL and the Table API <a class="header-anchor" href="#flink-sql-and-the-table-api" aria-label="Permalink to &quot;Flink SQL and the Table API&quot;">​</a></h3><p>Flink SQL is not a toy layer — it compiles to the same operator graph as DataStream code, so <code>MATCH_RECOGNIZE</code>, windowing TVFs (<code>TUMBLE</code>, <code>HOP</code>, <code>CUMULATE</code>), and upsert/changelog sinks all inherit the same checkpoint and state machinery. Production teams increasingly write streaming jobs as SQL for exactly this reason: same correctness contract, a fraction of the code. The DataStream API remains for what SQL can&#39;t express — custom timers, low-level state, async patterns.</p><h2 id="beam-the-portable-model" tabindex="-1">Beam: the portable model <a class="header-anchor" href="#beam-the-portable-model" aria-label="Permalink to &quot;Beam: the portable model&quot;">​</a></h2><p>Beam answers four questions — <strong>What</strong> are you computing, <strong>Where</strong> in event time, <strong>When</strong> do results materialize, <strong>How</strong> do refinements relate — and turns them into one model that runs over batch <em>and</em> stream:</p><ul><li><strong><code>PCollection</code></strong> — the dataset (bounded or unbounded).</li><li><strong><code>PTransform</code> / <code>ParDo</code></strong> — per-element processing; <code>DoFn</code> is the unit of user logic.</li><li><strong><code>GroupByKey</code> / windowing / triggers</strong> — grouping, event-time slicing, and materialization timing.</li><li><strong>Runners</strong> — the same pipeline executes on Flink, Dataflow, Spark, or the local Direct runner; the runner translates the model, it doesn&#39;t change the semantics.</li></ul><p>Two Beam specifics worth internalizing: <strong>PCollections are immutable</strong> — transforms produce new collections, which is what makes the model runner-agnostic and replayable — and <strong><code>DoFn</code> supports per-key state and timers</strong> (<code>@StateId</code>, <code>@TimerId</code>), so session logic and event-time callbacks are expressible portably, with the runner implementing them.</p>',9)),(r(),n(d,null,{default:t(()=>[o(s,{id:"mermaid-908",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20beam%5B%22Beam%20model%20%E2%80%94%20write%20once%22%5D%0A%20%20%20%20%20%20%20%20PC%5B%22PCollection%22%5D%20--%3E%20PD%5B%22ParDo%20%2F%20DoFn%22%5D%0A%20%20%20%20%20%20%20%20PD%20--%3E%20W%5B%22Window.into%22%5D%0A%20%20%20%20%20%20%20%20W%20--%3E%20GBK%5B%22GroupByKey%20%2F%20Combine%22%5D%0A%20%20%20%20%20%20%20%20GBK%20--%3E%20TR%5B%22Trigger%3A%20when%20to%20emit%22%5D%0A%20%20%20%20end%0A%20%20%20%20TR%20--%3E%20R1%5B%22Runner%3A%20Flink%22%5D%0A%20%20%20%20TR%20--%3E%20R2%5B%22Runner%3A%20Dataflow%22%5D%0A%20%20%20%20TR%20--%3E%20R3%5B%22Runner%3A%20Spark%22%5D%0A%20%20%20%20TR%20-.-%3E%7C%22same%20code%2C%3Cbr%2F%3Esame%20semantics%22%7C%20SAME%5B%22One%20pipeline%2C%3Cbr%2F%3Ebatch%20or%20stream%22%5D%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[i(" Loading... ",-1)])]),_:1})),e[11]||(e[11]=a('<p><strong>&quot;Beam = model, Flink = engine&quot;</strong> is not marketing shorthand — it&#39;s the architecture: Beam defines <em>semantics</em> (event-time correctness, windows, triggers, accumulators) and the runner implements them. A Flink-native job gets deeper control (async I/O, finer state TTL, lower-level APIs); a Beam job gets portability and a cleaner mental model.</p><details class="details custom-block"><summary>Where portability actually breaks</summary><p>The model is portable; the <em>implementation coverage</em> is not uniform. A pipeline that uses timers, state, or merging session windows runs on Flink and Dataflow but may fall back to emulation — or not run — on weaker runners. Splittable <code>DoFn</code>, some trigger combinations, and certain side-input patterns have runner-specific gaps; the Beam capability matrix is the reference, not a nice-to-have. Portability is real for the common 80% — windows, triggers, stateful DoFns, Kafka IO — and the other 20% is where you pin to a runner anyway. Treat &quot;runs anywhere&quot; as &quot;runs on the runners that matter to you.&quot;</p></details><h2 id="choosing-an-engine" tabindex="-1">Choosing an engine <a class="header-anchor" href="#choosing-an-engine" aria-label="Permalink to &quot;Choosing an engine&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><strong>Apache Beam</strong></th><th><strong>Apache Flink</strong></th><th><strong>Spark Structured Streaming</strong></th></tr></thead><tbody><tr><td>Programming model</td><td>Declarative (What/Where/When/How), portable</td><td>DataStream/Table API, engine-native</td><td>Micro-batch DataFrame API + continuous mode</td></tr><tr><td>Latency</td><td>Runner-dependent (Flink/Dataflow: true streaming)</td><td>True streaming, ~ms–10s of ms</td><td>Micro-batch: ~100 ms–seconds; continuous mode rare</td></tr><tr><td>State</td><td>Runner-managed keyed state</td><td>First-class keyed state, RocksDB scale, TTL</td><td>State store with checkpoints; bounded by micro-batch</td></tr><tr><td>Event-time support</td><td>Canonical — windows, watermarks, triggers</td><td>Native — watermarks, allowed lateness</td><td>Event-time windows + watermarking, trigger semantics limited</td></tr><tr><td>Exactly-once</td><td>Runner + sink dependent</td><td>Checkpoints + 2PC sinks, mature</td><td>Checkpointed micro-batch + idempotent/transactional sinks</td></tr><tr><td>SQL</td><td>Beam SQL (Calcite, subset)</td><td>Flink SQL / Table API — production-grade</td><td>Spark SQL — strongest ecosystem</td></tr><tr><td>Best fit</td><td>Portability, Dataflow on GCP, one codebase batch+stream</td><td>High-throughput stateful streaming, fine control</td><td>Teams already on Spark, latency ≥seconds acceptable</td></tr></tbody></table><h3 id="when-kafka-streams-is-enough" tabindex="-1">When Kafka Streams is enough <a class="header-anchor" href="#when-kafka-streams-is-enough" aria-label="Permalink to &quot;When Kafka Streams is enough&quot;">​</a></h3><p>If your topology is <strong>Kafka in → transform → Kafka out</strong>, and you don&#39;t need multi-engine portability, <strong>Kafka Streams</strong> is often the right answer:</p><ul><li>A library in your app, not a cluster — no JobManager to run; scaling = more app instances; state lives in embedded RocksDB + changelog topics.</li><li>Exactly-once via Kafka transactions with zero extra infrastructure.</li><li>You lose: non-Kafka sources/sinks without Connect, the Beam model&#39;s portability, and Flink&#39;s richer event-time toolbox (side outputs, CEP, async state access).</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Kafka Streams is not a general engine</p><p>The moment you need to join against an external system at scale, serve queries on arbitrary state, or leave the Kafka ecosystem, you&#39;ve outgrown it — and a rewrite is the exit cost. If there&#39;s any real doubt, Flink; if the whole job is genuinely Kafka-in/Kafka-out, Streams is dramatically less ops.</p></div><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',9)),o(c,{questions:[{q:"A JobManager says the job cannot restart after a TaskManager died, even though most slots are free. Why?",options:["The network buffers leaked","State was lost","Checkpoint barrier alignment failed","The job needs as many slots as its maximum operator parallelism — a parallelism-4 operator needs 4 slots, and the lost TM dropped the pool below that"],correct:3,explain:"Slots are the scheduling unit: an app needs slots ≥ max operator parallelism. If the surviving TMs cannot supply them, the JobManager waits for resources rather than restart degraded."},{q:"A sink task acked checkpoint 42, then crashed before the JobManager sent the completion notification. What must the sink be able to do for exactly-once to hold?",options:["Re-read the source","Discard the transaction","Wait for checkpoint 43","Recover and commit the pre-committed transaction — once it voted, aborting would lose data"],correct:3,explain:"The ack is the 2PC commit vote. After voting, the transaction must be committable across failures — via a recoverable transaction handle — or the records it covers are lost."},{q:"You redeploy a job from a savepoint with a new operator added mid-pipeline. Stateful operators downstream of it lose their state. Why?",options:["The savepoint was corrupt","Default operator uids are generated from graph position — inserting an operator re-ids everything after it","The parallelism changed","RocksDB snapshots are not portable"],correct:1,explain:"Savepoint state maps by uid + state name. Generated uids shift when the graph changes; uid() on every operator is the fix — applied before the first stateful deploy."}]}),o(c,{questions:[{q:"A barrier arrives on one input of a two-input operator but not the other. What does the operator do in an aligned checkpoint?",options:["Duplicates the barrier","Buffers the arrived input until the barrier arrives on all inputs, then snapshots","Skips the checkpoint","Snapshots immediately"],correct:1,explain:"Alignment is what makes the snapshot a consistent cut. It is also why backpressure stalls checkpoints — unaligned checkpoints let the barrier overtake in-flight records to keep working under load."},{q:"Why is RocksDB the default state backend recommendation for production streaming jobs?",options:["It avoids serialization","It is required for savepoints","State size is not heap-bound and incremental checkpoints upload only changed SSTables","It is faster than heap for all access"],correct:2,explain:"Heap state backends bound you to JVM memory and full snapshots. RocksDB spills to local disk, snapshots incrementally, and scales to TBs of keyed state."},{q:"What makes an application end-to-end exactly-once rather than just internally exactly-once?",options:["Task chaining","Faster checkpoints","RocksDB state backend","A resettable source plus a sink that is transactional (2PC) or idempotent"],correct:3,explain:"Exactly-once is end-to-end: source replay + state snapshot + atomic commit. A sink that cannot participate in 2PC or be idempotent reverts the whole pipeline to at-least-once."},{q:"Beam pipelines run on Flink, Dataflow, and Spark with the same code. What actually transfers?",options:["Only the SQL","The binary artifacts","The semantics — PCollections, windows, triggers, event-time model; the runner implements execution","The checkpoint format"],correct:2,explain:"Beam is a specification of semantics plus SDKs. Runners translate the model to engine primitives — that is the Beam = model, engine = runner split."},{q:"Job: read Kafka topic, enrich from another Kafka topic, write to a Kafka topic. Which engine is dramatically less ops than running Flink?",options:["Beam on Dataflow","Flink SQL","Spark","Kafka Streams — a library in your app; scaling is more instances, exactly-once via Kafka transactions with no separate engine to operate"],correct:3,explain:"For pure Kafka-in/Kafka-out topologies Kafka Streams removes the cluster entirely. You lose non-Kafka IO, the Beam model, and the richer event-time toolbox of Flink."}]}),e[12]||(e[12]=a('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://nightlies.apache.org/flink/flink-docs-stable/" target="_blank" rel="noreferrer">Apache Flink documentation</a></li><li><a href="https://nightlies.apache.org/flink/flink-docs-stable/docs/dev/datastream/fault-tolerance/checkpointing/" target="_blank" rel="noreferrer">Flink checkpointing &amp; fault tolerance</a></li><li><a href="https://nightlies.apache.org/flink/flink-docs-stable/docs/ops/state/state_backends/" target="_blank" rel="noreferrer">Flink state backends</a></li><li><a href="https://nightlies.apache.org/flink/flink-docs-stable/docs/ops/state/savepoints/" target="_blank" rel="noreferrer">Flink savepoints</a></li><li><a href="https://beam.apache.org/documentation/programming-guide/" target="_blank" rel="noreferrer">Apache Beam Programming Guide</a></li><li><a href="https://kafka.apache.org/documentation/streams/" target="_blank" rel="noreferrer">Kafka Streams documentation</a></li><li><strong>Stream Processing with Apache Flink</strong> — Fabian Hueske &amp; Vasiliki Kalavri (2019), <a href="https://www.oreilly.com/library/view/stream-processing-with/9781491974285/" target="_blank" rel="noreferrer">O&#39;Reilly</a></li><li><a href="https://spark.apache.org/docs/latest/structured-streaming-programming-guide.html" target="_blank" rel="noreferrer">Spark Structured Streaming guide</a></li><li><a href="https://lamport.azurewebsites.net/pubs/chandy.pdf" target="_blank" rel="noreferrer">Chandy–Lamport distributed snapshots (the paper checkpoints are built on)</a></li></ul>',2))])}const S=p(u,[["render",g]]);export{T as __pageData,S as default};
